// The Agent page in its OrcaSlicer import mode (?panel=orca-import): the
// window File › Import › Import from OrcaSlicer… opens. It speaks the same
// bridge as the welcome-back window; each button is a shell_action the
// window carries out (Home/OrcaImportWindow.cpp).

import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { OrcaImport, OrcaImportActions } from './components/OrcaImport';

export function OrcaImportApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  const actions = useMemo<OrcaImportActions>(
    () => ({
      importPrinters: (printers) => client.send('shell_action', { action: 'import', printers }),
      chooseFolder: () => client.send('shell_action', { action: 'choose_folder' }),
      close: () => client.send('shell_action', { action: 'close' }),
    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title="This window could not reach JusPrin" detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.orcaImport) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--orca-import">
      <OrcaImport state={state.orcaImport} actions={actions} />
    </div>
  );
}
// File › Import › Import from OrcaSlicer…: the printers an OrcaSlicer folder
// has, the ones JusPrin already has marked and skipped, and once imported,
// what became of each (canvas "JusPrin v2", boards orca-import-02 found,
// 03 imported, 04 nothing new, 05 no folder). The window's title bar carries
// the title; the host finds the folder and does the importing.

import { useEffect, useState } from 'react';
import type { OrcaImportLine, OrcaImportPayload } from '../bridge/protocol';
import { afterPaint } from '@shared/afterPaint';
import { OrcaImportResultLines, OrcaPrinterList } from './OrcaImportLists';

export interface OrcaImportActions {
  // The printers left ticked, by name.
  importPrinters: (printers: string[]) => void;
  chooseFolder: () => void;
  close: () => void;
}

const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;

function Folder({ path, looked, onChoose }: { path: string; looked?: boolean; onChoose?: () => void }) {
  return (
    <div className="orca-import-folder">
      <span className="jp-icon jp-icon-monitor" aria-hidden="true" />
      <span className="orca-import-folder-path">{looked ? `Looked in ${path}` : path}</span>
      {onChoose && <button type="button" className="link" onClick={onChoose}>Choose another folder…</button>}
    </div>
  );
}

// Board 03: the same lines as board 17 on the first launch. One printer is
// named as the menu shows it; several are counted, since the list below names
// each. The page isn't told the open project's printer, so it says only that
// the printer stayed.
function Result({ result }: { result: OrcaImportLine[] }) {
  const printers = result.filter((line) => line.kind === 'printer' && line.imported);
  const where = 'in the printer menu at the top of the window. ';
  return <>
    <p className="orca-import-lead">
      {printers.length === 1 && `${printers[0].renamedTo || printers[0].name} is now ${where}`}
      {printers.length > 1 && `The ${printers.length} imported printers are now ${where}`}
      The open project still uses the same printer as before. OrcaSlicer’s own files were not changed.
    </p>
    <OrcaImportResultLines lines={result} />
  </>;
}

export function OrcaImport({ state, actions }: { state: OrcaImportPayload; actions: OrcaImportActions }) {
  // Importing holds the app for a while; the buttons say so meanwhile.
  // The host answers with the next screen once it is done.
  const [busy, setBusy] = useState(false);
  useEffect(() => setBusy(false), [state]);
  // Every printer JusPrin doesn't have yet starts ticked.
  const fresh = (state.printers ?? []).filter((printer) => !printer.already).map((printer) => printer.name);
  const [chosen, setChosen] = useState(fresh);
  // A new list, as after choosing another folder, starts over; the same one pushed again does not.
  const listed = fresh.join('\n');
  useEffect(() => setChosen(fresh), [listed]);
  const choose = (name: string, ticked: boolean) =>
    setChosen((now) => (ticked ? [...now, name] : now.filter((one) => one !== name)));
  const run = (action: () => void) => {
    setBusy(true);
    afterPaint(action);
  };
  const folder = state.folder ?? '';
  const newPrinters = state.newPrinters ?? 0;

  let body;
  let buttons;
  switch (state.screen) {
    case 'imported':
      body = <Result result={state.result ?? []} />;
      buttons = <button type="button" className="primary" onClick={actions.close}>Done</button>;
      break;
    case 'nothing_new':
      body = <>
        <p className="orca-import-lead">Every printer in this OrcaSlicer folder is already in JusPrin, so there is nothing to import.</p>
        <OrcaPrinterList printers={state.printers ?? []} />
        <Folder path={folder} onChoose={actions.chooseFolder} />
      </>;
      buttons = <button type="button" className="primary" onClick={actions.close}>Close</button>;
      break;
    case 'no_folder':
    case 'no_printers':
      body = <>
        <p className="orca-import-lead">
          {state.screen === 'no_folder'
            ? 'JusPrin didn’t find OrcaSlicer’s folder on this computer. '
            : 'JusPrin found no OrcaSlicer printers in this folder. '}
          If OrcaSlicer keeps its settings somewhere else, choose that folder.
        </p>
        <Folder path={folder} looked />
      </>;
      buttons = <>
        <button type="button" onClick={actions.close}>Cancel</button>
        <button type="button" className="primary" onClick={actions.chooseFolder}>Choose the folder…</button>
      </>;
      break;
    case 'found':
      body = <>
        <p className="orca-import-lead">
          {newPrinters > 0
            ? `JusPrin found ${plural(newPrinters, 'printer', 'printers')} in OrcaSlicer that it doesn’t have yet. JusPrin copies ${newPrinters === 1 ? 'it' : 'them'} with ${newPrinters === 1 ? 'its' : 'their'} filaments, settings and printer connections. `
            : 'JusPrin found filaments or settings in OrcaSlicer that it doesn’t have yet. JusPrin copies them. '}
          OrcaSlicer keeps its own copy.
        </p>
        <OrcaPrinterList printers={state.printers ?? []} chosen={chosen} onChoose={choose} disabled={busy} />
        <Folder path={folder} onChoose={busy ? undefined : actions.chooseFolder} />
      </>;
      buttons = <>
        <button type="button" disabled={busy} onClick={actions.close}>Cancel</button>
        <button type="button" className="primary" disabled={busy || (newPrinters > 0 && chosen.length === 0)}
          onClick={() => run(() => actions.importPrinters(chosen))}>
          {busy ? 'Importing…' : chosen.length > 0 ? `Import ${plural(chosen.length, 'printer', 'printers')}` : 'Import'}
        </button>
      </>;
      break;
  }

  return (
    <div className="orca-import" data-testid="orca-import">
      <div className="orca-import-content">
        {body}
        {state.error && <p className="orca-import-error" role="alert">{state.error}</p>}
      </div>
      <div className="orca-import-buttons">{buttons}</div>
    </div>
  );
}
// The printer list and the result lines an OrcaSlicer import shows: on the
// first launch's Printers step (Home page, canvas boards 07 and 17) and in
// File › Import › Import from OrcaSlicer… (this page, boards orca-import-02
// to 04). Both pages draw this one markup, with its own stylesheet, so the
// two cannot drift apart.

import './OrcaImportLists.css';

export interface OrcaPrinterRow {
  name: string;
  // JusPrin has it already, so the import skips it.
  already: boolean;
}

export interface OrcaImportResultLine {
  kind: 'printer' | 'filament' | 'process';
  name: string;
  renamedTo: string;
  imported: boolean;
  // Why it was not imported, as a sentence.
  reason: string;
}

// With `chosen` and `onChoose`, each printer JusPrin doesn't have yet has a
// tick box, and only the ticked ones are imported.
export function OrcaPrinterList({ printers, chosen, onChoose, disabled }: {
  printers: OrcaPrinterRow[];
  chosen?: string[];
  onChoose?: (name: string, ticked: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <ul className="orca-import-list" aria-label="OrcaSlicer printers">
      {printers.map(({ name, already }, index) => (
        <li key={`${name}:${index}`} className={already ? 'orca-import-row orca-import-row--already' : 'orca-import-row'}>
          {!already && chosen && onChoose ? (
            <label className="orca-import-choice">
              <input type="checkbox" checked={chosen.includes(name)} disabled={disabled}
                onChange={(event) => onChoose(name, event.target.checked)} />
              <span className="orca-import-row-name">{name}</span>
            </label>
          ) : <>
            <span className={`orca-import-icon ${already ? 'orca-import-icon--check' : 'orca-import-icon--printer'}`} aria-hidden="true" />
            <span className="orca-import-row-name">{name}</span>
          </>}
          {already && <span className="orca-import-row-status">Already in JusPrin</span>}
        </li>
      ))}
    </ul>
  );
}

function status(line: OrcaImportResultLine) {
  if (!line.imported) return line.reason;
  return line.renamedTo ? `Imported as ‘${line.renamedTo}’` : 'Imported';
}

// Printers and processes a line each, the outcome under the name; filaments
// as a count with the names of those imported, and any not imported listed
// so each says why.
export function OrcaImportResultLines({ lines }: { lines: OrcaImportResultLine[] }) {
  const filaments = lines.filter((line) => line.kind === 'filament');
  const imported = filaments.filter((line) => line.imported).map((line) => line.renamedTo || line.name);
  const importedFilaments = imported.length;
  const listed = lines.filter((line) => line.kind !== 'filament' || !line.imported);
  const noun = filaments.length === 1 ? 'filament' : 'filaments';
  return <>
    {listed.length > 0 && (
      <ul className="orca-import-list" aria-label="Imported">
        {listed.map((line, index) => (
          <li key={`${line.kind}:${line.name}:${index}`} className="orca-import-row">
            <span className={`orca-import-icon ${line.imported ? 'orca-import-icon--done' : 'orca-import-icon--warning'}`}
              aria-hidden="true" />
            <span className="orca-import-line">
              <span className="orca-import-row-name">{line.name}</span>
              <span className="orca-import-row-status">{status(line)}</span>
            </span>
          </li>
        ))}
      </ul>
    )}
    {filaments.length > 0 && (
      <p className="orca-import-count">
        {importedFilaments === filaments.length
          ? `${filaments.length} ${noun} imported`
          : `${importedFilaments} of ${filaments.length} ${noun} imported`}
        {importedFilaments > 0 ? `: ${imported.join(', ')}.` : '.'}
      </p>
    )}
  </>;
}
