.onboarding-error {
  font: var(--font-label);
  color: var(--status-danger);
}

/* The design system's Button/Link: text only, Label Bold, action/primary. */
.onboarding-link {
  align-self: flex-start;
  padding: 4px 0;
  font: var(--font-label-bold);
  color: var(--action-primary);
  text-align: left;
  background: none;
  border: 0;
  cursor: pointer;
}

.onboarding-link:hover:not(:disabled) {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.onboarding-link:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}
.onboarding-source-path {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.onboarding-actions {
  display: flex;
  gap: 12px;
}

/* What the welcome finished, above the first printer screen's headline. */
.onboarding-done {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.onboarding-done .glyph-check {
  background: var(--status-success);
}

/* The free credits, and who signed in on a smaller line under them. */
.onboarding-done-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.onboarding-done-detail {
  font: var(--font-label);
  color: var(--text-secondary);
}

/* Continue and Skip for now, the note on skipping under them. */
.onboarding-step-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.onboarding-step-group .onboarding-actions {
  align-items: center;
}

.onboarding-step-group .onboarding-link {
  align-self: center;
}

.onboarding-note {
  font: var(--font-label);
  color: var(--text-tertiary);
}


/* Below the width of the welcome row its two columns stack. */
@media (max-width: 1168px) {
  .onboarding-welcome {
    flex-direction: column;
    align-items: stretch;
  }

