constexpr const char* kSection = "jusprin_agent";

// A server named here, such as a staging or self-hosted one, is the one the
// account signs in to instead of the default. JusPrin v1 kept its own server
// here too; the v1 import leaves that behind.
constexpr const char* kServerSection = "jusprin_server";

std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }
// An account provider keeps the account's email and the wire format of each
// of its models beside the token.
std::string account_item_for(const std::string& provider) { return provider + "_account"; }
std::string formats_item_for(const std::string& provider) { return provider + "_model_formats"; }

// The server JUSPRIN_SERVER_URL names, otherwise the settings file's. The
// variable lets a test run reach a staging server without writing a settings
// file before launch, which would stop the v1 import.
std::string server_base_url(const AppConfig* config)
{
    if (const char* chosen = std::getenv("JUSPRIN_SERVER_URL"); chosen != nullptr && *chosen != '\0')
        return chosen;
    }
    if (mode == AgentPageMode::PrinterPanel)
        url += "?panel=printer";
    else if (mode == AgentPageMode::Preferences)
        url += "?panel=preferences";
    else if (mode == AgentPageMode::WelcomeBack)
        url += "?panel=welcome";
    else if (mode == AgentPageMode::OrcaImport)
        url += "?panel=orca-import";
    return url;
}
// Which of the page's surfaces this view is. The page reads it from the query
// string it is loaded with (see main.tsx):
//   Conversation   the docked panel: header, chat list, thread, composer;
//   PrinterPanel   Home's printer conversation: the printer session's own
//                  header, pinned card and chips around the same thread;
//   Preferences    JusPrin's Preferences window, whose Agent section is
//                  where the agent is set up and changed.
//   WelcomeBack    the window shown once after a JusPrin v1 setup was
//                  imported: what came along, and the account it signs in to.
//   OrcaImport     File › Import › Import from OrcaSlicer…: the printers an
//                  OrcaSlicer folder has that JusPrin doesn't, and the result.
enum class AgentPageMode { Conversation, PrinterPanel, Preferences, WelcomeBack, OrcaImport };

